'use client';

import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  MouseSensor,
  TouchSensor,
  useSensor,
  useSensors,
  type Announcements,
  type DragEndEvent,
  type DragStartEvent,
  type UniqueIdentifier,
} from '@dnd-kit/core';
import { LayoutGroup } from 'motion/react';
import { useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import {
  boardCollision,
  boardKeyboardCoordinates,
  targetOf,
  type DropTarget,
} from './board-dnd';
import { BoardColumns, ColumnHeaders, Swimlanes } from './board-grid';
import { BOARD_NAME, COLUMNS, type Card, type ColumnId } from './data';
import {
  cardsIn,
  columnOf,
  INITIAL,
  laneNameOf,
  LOOP_AFTER_MS,
  placementOf,
  reducer,
  RESTING,
  SCRIPT,
  type View,
} from './session';
import { OverlayCard } from './task-card';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const MOUSE = { activationConstraint: { distance: 4 } };

const TOUCH = { activationConstraint: { delay: 180, tolerance: 6 } };

const KEYBOARD = { coordinateGetter: boardKeyboardCoordinates };

const INSTRUCTIONS = {
  draggable:
    'To pick up a card, press Space or Enter. The arrow keys move it to another column, or to another lane when the cards are grouped by person. Space or Enter drops it, Escape puts it back.',
};

const VIEWS: Segment<View>[] = [
  { value: 'board', label: 'Board' },
  { value: 'lanes', label: 'By person' },
];

function cardsWordOf(count: number) {
  if (count === 1) {
    return '1 card';
  }
  return `${count} cards`;
}

function limitsLineOf() {
  const limited = COLUMNS.filter((column) => column.limit !== null);
  const parts = limited.map((column) => `${column.name} ${column.limit}`);
  const list = parts.join(', ');
  return `Limits: ${list}`;
}

const LIMITS_LINE = limitsLineOf();

/** The drop glides the card to its new place; reduced motion puts it there at once. */
function dropAnimationOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return null;
  }
  return undefined;
}

/** On the board the headers cap their columns; above the lanes they stand apart. */
function bodyGapOf(view: View) {
  if (view === 'board') {
    return 'gap-0';
  }
  return 'gap-3';
}

function placeLineOf(target: DropTarget) {
  const column = columnOf(target.column).name;
  if (target.lane === undefined) {
    return column;
  }
  const lane = laneNameOf(target.lane);
  return `${column}, lane of ${lane}`;
}

/** Would one more card take the column past its limit? Said while the card hovers there. */
function limitHintOf(cards: Card[], cardId: string, column: ColumnId) {
  const target = columnOf(column);
  if (target.limit === null) {
    return '';
  }
  const inColumn = cardsIn(cards, column);
  const others = inColumn.filter((card) => card.id !== cardId);
  const countAfter = others.length + 1;
  if (countAfter <= target.limit) {
    return '';
  }
  return `, past its limit of ${target.limit}`;
}

export default function Boards03() {
  const { ref, isInView, isAutoplaying, state, act, isFinished, restart } =
    useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const travel = springOf(shouldReduceMotion);
  const groupId = useId();
  const dndId = useId();
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const sensors = useSensors(
    useSensor(MouseSensor, MOUSE),
    useSensor(TouchSensor, TOUCH),
    useSensor(KeyboardSensor, KEYBOARD)
  );
  const placement = placementOf(state);
  const draggedCard = state.cards.find((card) => card.id === draggedId);
  const isBoard = state.view === 'board';
  const isLanes = state.view === 'lanes';
  const meta = `${cardsWordOf(state.cards.length)} · ${LIMITS_LINE}`;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function titleOf(id: UniqueIdentifier) {
    const card = state.cards.find((candidate) => candidate.id === id);
    return card?.title ?? 'The card';
  }

  function currentPlaceOf(id: UniqueIdentifier) {
    const card = state.cards.find((candidate) => candidate.id === id);
    if (!card) {
      return 'its column';
    }
    return columnOf(card.column).name;
  }

  const announcements: Announcements = {
    onDragStart({ active }) {
      return `Picked up ${titleOf(active.id)}, in ${currentPlaceOf(active.id)}`;
    },
    onDragOver({ active, over }) {
      const target = targetOf(over?.id);
      const title = titleOf(active.id);
      if (!target) {
        return `${title} is not over a column`;
      }
      const hint = limitHintOf(state.cards, String(active.id), target.column);
      return `${title} is over ${placeLineOf(target)}${hint}`;
    },
    onDragEnd({ active, over }) {
      const target = targetOf(over?.id);
      const title = titleOf(active.id);
      if (!target) {
        return `${title} went back to ${currentPlaceOf(active.id)}`;
      }
      return `${title} dropped in ${placeLineOf(target)}`;
    },
    onDragCancel({ active }) {
      return `Moving ${titleOf(active.id)} was cancelled. It is back in ${currentPlaceOf(active.id)}`;
    },
  };

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function startDrag({ active }: DragStartEvent) {
    setDraggedId(String(active.id));
  }

  function endDrag({ active, over }: DragEndEvent) {
    setDraggedId(null);
    const target = targetOf(over?.id);
    if (!target) {
      return;
    }
    act({
      type: 'moved',
      id: String(active.id),
      column: target.column,
      lane: target.lane,
      isDrop: true,
    });
  }

  function cancelDrag() {
    setDraggedId(null);
  }

  function changeView(view: View) {
    act({ type: 'viewChanged', view });
  }

  function openComposer(column: ColumnId) {
    act({ type: 'composerOpened', column });
    focusLater(`[data-composer="${column}"]`);
  }

  function closeComposer() {
    const column = state.composerColumn;
    act({ type: 'composerClosed' });
    if (column) {
      focusLater(`[data-add="${column}"]`);
    }
  }

  function typeComposer(value: string) {
    act({ type: 'composerTyped', value });
  }

  function addCard() {
    act({ type: 'cardAdded' });
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-6xl flex-col gap-4 p-4 @3xl:gap-5 @3xl:p-6'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <div className='flex min-w-0 flex-1 basis-56 flex-col gap-0.5'>
              <h1 className='text-lg font-semibold text-balance'>
                {BOARD_NAME}
              </h1>
              <p className='text-muted-foreground text-xs tabular-nums'>
                {meta}
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
            <Segments
              value={state.view}
              segments={VIEWS}
              label='Arrange the cards'
              onValueChange={changeView}
            />
          </header>

          <DndContext
            id={dndId}
            sensors={sensors}
            collisionDetection={boardCollision}
            accessibility={{
              announcements,
              screenReaderInstructions: INSTRUCTIONS,
            }}
            onDragStart={startDrag}
            onDragEnd={endDrag}
            onDragCancel={cancelDrag}
          >
            <div className='relative -mx-4 overflow-x-auto overscroll-x-contain px-4 pb-2 @3xl:mx-0 @3xl:px-0'>
              <div
                className={cn(
                  'flex min-w-[44rem] flex-col',
                  bodyGapOf(state.view)
                )}
              >
                <ColumnHeaders cards={state.cards} view={state.view} />
                <LayoutGroup id={groupId}>
                  {isBoard && (
                    <BoardColumns
                      state={state}
                      placement={placement}
                      travel={travel}
                      onOpenComposer={openComposer}
                      onCloseComposer={closeComposer}
                      onTypeComposer={typeComposer}
                      onAddCard={addCard}
                    />
                  )}
                  {isLanes && (
                    <Swimlanes
                      state={state}
                      placement={placement}
                      travel={travel}
                    />
                  )}
                </LayoutGroup>
              </div>
            </div>
            <DragOverlay dropAnimation={dropAnimationOf(shouldReduceMotion)}>
              {draggedCard && <OverlayCard card={draggedCard} />}
            </DragOverlay>
          </DndContext>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useDroppable } from '@dnd-kit/core';
import { AnimatePresence, motion, type Transition } from 'motion/react';
import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { PlusIcon, TriangleAlertIcon } from '@/registry/ndeko/lib/icons';
import { fadePresence } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Input } from '@/registry/ndeko/ui/input';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import { dropIdOf } from './board-dnd';
import {
  COLUMNS,
  TITLE_MAX_LENGTH,
  type Card,
  type Column,
  type ColumnId,
  type LaneId,
} from './data';
import {
  cardsIn,
  cardsInCell,
  cardsOfLane,
  laneNameOf,
  lanesOf,
  overByOf,
  type BoardState,
  type View,
} from './session';
import { TaskCard } from './task-card';

const ALERT_IN = {
  initial: { opacity: 0, scale: 0.6 },
  animate: { opacity: 1, scale: 1 },
  exit: { opacity: 0, scale: 0.6 },
};

const ALERT_FADE = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0 },
};

function alertMotionOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return ALERT_FADE;
  }
  return ALERT_IN;
}

function cardsWordOf(count: number) {
  if (count === 1) {
    return '1 card';
  }
  return `${count} cards`;
}

function phraseOf(column: Column, count: number) {
  const over = overByOf(column, count);
  if (over > 0) {
    return `Over by ${over}`;
  }
  return `${count} of ${column.limit}`;
}

function spokenCountOf(column: Column, count: number) {
  const cards = cardsWordOf(count);
  const over = overByOf(column, count);
  if (over > 0) {
    return `${cards}, over its limit of ${column.limit} by ${over}`;
  }
  return `${cards}, limit ${column.limit}`;
}

/** On the board the header caps its column; above the lanes it stands alone. */
function headerShapeOf(view: View) {
  if (view === 'board') {
    return 'rounded-t-xl';
  }
  return 'rounded-xl';
}

function headerToneOf(isOver: boolean) {
  if (isOver) {
    return 'bg-warning/15';
  }
  return 'bg-foreground/[0.03]';
}

function countToneOf(isOver: boolean) {
  if (isOver) {
    return 'text-warning-foreground font-medium';
  }
  return 'text-muted-foreground';
}

type ColumnHeaderProps = {
  column: Column;
  count: number;
  view: View;
};

/** The signature of the board: past its limit, the header tints and its count rolls to Over by. */
function ColumnHeader({ column, count, view }: ColumnHeaderProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const alertMotion = alertMotionOf(shouldReduceMotion);
  const hasLimit = column.limit !== null;
  const overBy = overByOf(column, count);
  const isOver = overBy > 0;

  return (
    <div
      className={cn(
        'flex h-10 min-w-0 items-center gap-2 px-3 transition-colors duration-300 ease-(--ease-out-strong)',
        headerShapeOf(view),
        headerToneOf(isOver)
      )}
    >
      <span
        aria-hidden='true'
        className={cn('size-2 shrink-0 rounded-full', column.dot)}
      />
      <h2 className='min-w-0 truncate text-[13px] font-medium'>
        {column.name}
      </h2>
      <span
        className={cn(
          'ms-auto flex shrink-0 items-center gap-1 text-xs tabular-nums transition-colors duration-300',
          countToneOf(isOver)
        )}
      >
        <AnimatePresence initial={false}>
          {isOver && (
            <motion.span key='alert' className='flex' {...alertMotion}>
              <TriangleAlertIcon className='size-3.5' />
            </motion.span>
          )}
        </AnimatePresence>
        {hasLimit && (
          <WordRoll
            text={phraseOf(column, count)}
            value={count}
            accessibleText={spokenCountOf(column, count)}
          />
        )}
        {!hasLimit && (
          <span>
            <MotionNumber value={count} />
            <span className='sr-only'> cards</span>
          </span>
        )}
      </span>
    </div>
  );
}

function countIn(cards: Card[], column: ColumnId) {
  const inColumn = cardsIn(cards, column);
  return inColumn.length;
}

export function ColumnHeaders({ cards, view }: { cards: Card[]; view: View }) {
  return (
    <div className='grid grid-cols-4 gap-3'>
      {COLUMNS.map((column) => (
        <ColumnHeader
          key={column.id}
          column={column}
          count={countIn(cards, column.id)}
          view={view}
        />
      ))}
    </div>
  );
}

function targetToneOf(isOver: boolean) {
  if (isOver) {
    return 'bg-primary/[0.06] ring-2 ring-primary/25';
  }
  return undefined;
}

type DropAreaProps = {
  id: string;
  label: string;
  className: string;
  children: React.ReactNode;
};

/** A column or a cell takes a drop anywhere, even when it is empty. */
function DropArea({ id, label, className, children }: DropAreaProps) {
  const { setNodeRef, isOver } = useDroppable({ id });

  return (
    <div
      ref={setNodeRef}
      role='group'
      aria-label={label}
      className={cn(
        'transition-[background-color,box-shadow] duration-150',
        className,
        targetToneOf(isOver)
      )}
    >
      {children}
    </div>
  );
}

type CardListProps = {
  cards: Card[];
  state: BoardState;
  placement: string;
  travel: Transition;
};

function CardList({ cards, state, placement, travel }: CardListProps) {
  return (
    <ul className='flex flex-col gap-2'>
      {cards.map((card) => (
        <li key={card.id}>
          <TaskCard
            card={card}
            placement={placement}
            travel={travel}
            isFresh={state.freshId === card.id}
          />
        </li>
      ))}
    </ul>
  );
}

type QuickAddProps = {
  column: Column;
  isOpen: boolean;
  text: string;
  onOpen: (column: ColumnId) => void;
  onClose: () => void;
  onType: (value: string) => void;
  onAdd: () => void;
};

/** Enter adds the card and keeps the field for the next one; Escape leaves. */
function QuickAdd({
  column,
  isOpen,
  text,
  onOpen,
  onClose,
  onType,
  onAdd,
}: QuickAddProps) {
  const hintId = useId();
  const fade = fadePresence();

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onAdd();
  }

  function leaveOnEscape(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onClose();
  }

  return (
    <AnimatePresence mode='popLayout' initial={false}>
      {isOpen && (
        <motion.form
          key='composer'
          noValidate
          onSubmit={submit}
          className='flex flex-col gap-1.5'
          {...fade}
        >
          <Input
            size='sm'
            data-composer={column.id}
            value={text}
            maxLength={TITLE_MAX_LENGTH}
            autoComplete='off'
            placeholder='Card title'
            aria-label={`New card in ${column.name}`}
            aria-describedby={hintId}
            onKeyDown={leaveOnEscape}
            onChange={(event) => onType(event.target.value)}
          />
          <p
            id={hintId}
            className='text-muted-foreground flex flex-wrap items-center gap-1 px-0.5 text-[11px]'
          >
            <Kbd>Enter</Kbd> adds <Kbd>Esc</Kbd> leaves
          </p>
        </motion.form>
      )}
      {!isOpen && (
        <motion.div key='add' {...fade}>
          <button
            type='button'
            data-add={column.id}
            onClick={() => onOpen(column.id)}
            className='text-muted-foreground hover:text-foreground hover:bg-foreground/5 focus-visible:ring-ring/25 flex h-8 w-full shrink-0 cursor-pointer items-center gap-2 rounded-md px-2 text-[13px] transition-colors duration-150 outline-none focus-visible:ring-[3px]'
          >
            <PlusIcon className='size-4' />
            Add card
          </button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

type BoardColumnsProps = {
  state: BoardState;
  placement: string;
  travel: Transition;
  onOpenComposer: (column: ColumnId) => void;
  onCloseComposer: () => void;
  onTypeComposer: (value: string) => void;
  onAddCard: () => void;
};

export function BoardColumns({
  state,
  placement,
  travel,
  onOpenComposer,
  onCloseComposer,
  onTypeComposer,
  onAddCard,
}: BoardColumnsProps) {
  return (
    <div className='grid grid-cols-4 gap-3'>
      {COLUMNS.map((column) => {
        const cards = cardsIn(state.cards, column.id);
        const isEmpty = cards.length === 0;

        return (
          <DropArea
            key={column.id}
            id={dropIdOf(column.id)}
            label={column.name}
            className='bg-foreground/[0.03] relative flex min-h-48 flex-col gap-2 rounded-b-xl p-2'
          >
            <CardList
              cards={cards}
              state={state}
              placement={placement}
              travel={travel}
            />
            {isEmpty && (
              <p className='hairline-border border-foreground/20 text-muted-foreground flex h-16 items-center justify-center rounded-lg border-dashed px-3 text-center text-xs'>
                Drop a card here
              </p>
            )}
            <QuickAdd
              column={column}
              isOpen={state.composerColumn === column.id}
              text={state.composerText}
              onOpen={onOpenComposer}
              onClose={onCloseComposer}
              onType={onTypeComposer}
              onAdd={onAddCard}
            />
          </DropArea>
        );
      })}
    </div>
  );
}

function laneCountOf(cards: Card[], lane: LaneId) {
  const inLane = cardsOfLane(cards, lane);
  return inLane.length;
}

/** Nobody holds these cards yet: an empty dashed seat, since no one is there. */
function LaneMark({ lane }: { lane: LaneId }) {
  if (lane === 'unassigned') {
    return (
      <span
        aria-hidden='true'
        className='border-foreground/25 size-5 shrink-0 rounded-full border border-dashed'
      />
    );
  }
  return <Avatar seed={laneNameOf(lane)} className='size-5' />;
}

type SwimlanesProps = {
  state: BoardState;
  placement: string;
  travel: Transition;
};

/** One lane per person: a card dropped in another lane changes hands. */
export function Swimlanes({ state, placement, travel }: SwimlanesProps) {
  const lanes = lanesOf(state.cards);

  return (
    <div className='flex flex-col gap-4'>
      {lanes.map((lane) => {
        const laneName = laneNameOf(lane);
        const laneCount = laneCountOf(state.cards, lane);

        return (
          <section
            key={lane}
            aria-label={laneName}
            className='flex flex-col gap-2'
          >
            <h3 className='flex items-center gap-2 px-1 text-[13px] font-medium'>
              <LaneMark lane={lane} />
              {laneName}
              <span className='text-muted-foreground text-xs font-normal tabular-nums'>
                {cardsWordOf(laneCount)}
              </span>
            </h3>
            <div className='grid grid-cols-4 gap-3'>
              {COLUMNS.map((column) => (
                <DropArea
                  key={column.id}
                  id={dropIdOf(column.id, lane)}
                  label={`${column.name}, ${laneName}`}
                  className='bg-foreground/[0.03] flex min-h-16 flex-col rounded-xl p-2'
                >
                  <CardList
                    cards={cardsInCell(state.cards, column.id, lane)}
                    state={state}
                    placement={placement}
                    travel={travel}
                  />
                </DropArea>
              ))}
            </div>
          </section>
        );
      })}
    </div>
  );
}

'use client';

import { useDraggable } from '@dnd-kit/core';
import { motion, type Transition } from 'motion/react';
import { memo } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';

import type { Card } from './data';
import { columnOf, personOf } from './session';

export const CARD_SURFACE =
  'bg-card hairline-ring ring-border rounded-lg shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.04]';

const ARRIVAL = { opacity: 0, y: 4 };

const ARRIVAL_FADE = { opacity: 0 };

const SHOWN = { opacity: 1, y: 0 };

const LIFT: Transition = { type: 'spring', bounce: 0, duration: 0.25 };

const INSTANT: Transition = { duration: 0 };

function firstNameOf(name: string) {
  const [first] = name.split(' ');
  return first;
}

function holderOf(card: Card) {
  const person = personOf(card.assignee);
  if (person) {
    return person.name;
  }
  return 'Unassigned';
}

export function cardLabelOf(card: Card) {
  const column = columnOf(card.column).name;
  const holder = holderOf(card);
  return `${card.number} ${card.title}, ${holder}, in ${column}`;
}

/** A card added here arrives once; every other card is already there, whatever the view. */
function arrivalOf(isFresh: boolean, shouldReduceMotion: boolean) {
  if (!isFresh) {
    return false;
  }
  if (shouldReduceMotion) {
    return ARRIVAL_FADE;
  }
  return ARRIVAL;
}

type CardBodyProps = {
  card: Card;
};

/** The content of a card. Memoised, so a drag re-renders only the thin wrapper around it. */
export const CardBody = memo(function CardBody({ card }: CardBodyProps) {
  const person = personOf(card.assignee);
  const holder = holderOf(card);
  const firstName = firstNameOf(holder);

  return (
    <div className='flex flex-col gap-2 p-2.5'>
      <p className='line-clamp-2 text-[13px] leading-snug font-medium text-pretty'>
        {card.title}
      </p>
      <div className='flex items-center gap-2'>
        <span className='text-muted-foreground font-mono text-[11px] tabular-nums'>
          {card.number}
        </span>
        <span className='ms-auto flex min-w-0 items-center gap-1.5'>
          {person && <Avatar seed={person.name} className='size-5' />}
          {!person && (
            <span
              aria-hidden='true'
              className='border-foreground/25 size-5 shrink-0 rounded-full border border-dashed'
            />
          )}
          <span className='text-muted-foreground truncate text-xs'>
            {firstName}
          </span>
        </span>
      </div>
    </div>
  );
});

type TaskCardProps = {
  card: Card;
  /** Where every card sits: the card measures itself again only when it changes. */
  placement: string;
  travel: Transition;
  isFresh: boolean;
};

/**
 * A card keeps its layout id across columns, lanes and views, so it glides to its new place. A
 * card a person dropped takes a new one: it is already where it was let go.
 */
export function TaskCard({ card, placement, travel, isFresh }: TaskCardProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: card.id,
  });

  return (
    <motion.div
      layout='position'
      layoutId={`${card.id}:${card.drops}`}
      layoutDependency={placement}
      transition={{ layout: travel }}
      initial={arrivalOf(isFresh, shouldReduceMotion)}
      animate={SHOWN}
    >
      <div
        ref={setNodeRef}
        {...attributes}
        {...listeners}
        aria-label={cardLabelOf(card)}
        className={cn(
          CARD_SURFACE,
          'focus-visible:ring-ring/25 cursor-grab touch-manipulation outline-none select-none focus-visible:ring-[3px] active:cursor-grabbing',
          isDragging && 'opacity-40'
        )}
      >
        <CardBody card={card} />
      </div>
    </motion.div>
  );
}

/** The card under the pointer: lifted on a raised surface while it travels. */
export function OverlayCard({ card }: { card: Card }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const lift = liftOf(shouldReduceMotion);

  return (
    <motion.div
      initial={{ scale: 1 }}
      animate={{ scale: lift.scale }}
      transition={lift.transition}
      className='surface-raised cursor-grabbing rounded-lg'
    >
      <CardBody card={card} />
    </motion.div>
  );
}

function liftOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return { scale: 1, transition: INSTANT };
  }
  return { scale: 1.02, transition: LIFT };
}

import {
  pointerWithin,
  rectIntersection,
  type ClientRect,
  type CollisionDetection,
  type KeyboardCoordinateGetter,
  type UniqueIdentifier,
} from '@dnd-kit/core';

import { COLUMNS, PEOPLE, type ColumnId, type LaneId } from './data';

type Direction = 'up' | 'down' | 'left' | 'right';

type Point = { x: number; y: number };

type Choice = { rect: ClientRect; cost: number };

export type DropTarget = { column: ColumnId; lane?: LaneId };

const DIRECTION_OF_KEY: Partial<Record<string, Direction>> = {
  ArrowUp: 'up',
  ArrowDown: 'down',
  ArrowLeft: 'left',
  ArrowRight: 'right',
};

/** A move across rows or columns costs this much more than a move along them. */
const ACROSS_WEIGHT = 3;

/** The dragged card lands this far inside the top of the place it goes to. */
const LANDING_INSET_PX = 8;

const LANE_SEPARATOR = '/';

export function dropIdOf(column: ColumnId, lane?: LaneId) {
  if (lane === undefined) {
    return column;
  }
  return `${lane}${LANE_SEPARATOR}${column}`;
}

function columnIdOf(value: string) {
  const column = COLUMNS.find((candidate) => candidate.id === value);
  return column?.id;
}

function laneIdOf(value: string): LaneId | undefined {
  if (value === 'unassigned') {
    return 'unassigned';
  }
  const person = PEOPLE.find((candidate) => candidate.id === value);
  return person?.id;
}

export function targetOf(id: UniqueIdentifier | undefined): DropTarget | null {
  if (id === undefined) {
    return null;
  }
  const parts = String(id).split(LANE_SEPARATOR);
  if (parts.length === 1) {
    const column = columnIdOf(parts[0]);
    if (!column) {
      return null;
    }
    return { column };
  }
  const lane = laneIdOf(parts[0]);
  const column = columnIdOf(parts[1]);
  if (!lane || !column) {
    return null;
  }
  return { column, lane };
}

/** A pointer drops where it is; the keyboard, which has none, drops where the card overlaps most. */
export const boardCollision: CollisionDetection = (args) => {
  if (args.pointerCoordinates) {
    return pointerWithin(args);
  }
  return rectIntersection(args);
};

function centerOf(rect: ClientRect): Point {
  const halfWidth = rect.width / 2;
  const halfHeight = rect.height / 2;
  const x = rect.left + halfWidth;
  const y = rect.top + halfHeight;
  return { x, y };
}

function isAhead(direction: Direction, from: Point, to: Point) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  if (direction === 'right') {
    return dx > 1;
  }
  if (direction === 'left') {
    return dx < -1;
  }
  if (direction === 'down') {
    return dy > 1;
  }
  return dy < -1;
}

function costOf(direction: Direction, from: Point, to: Point) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const width = Math.abs(dx);
  const height = Math.abs(dy);
  const isHorizontal = direction === 'left' || direction === 'right';
  if (isHorizontal) {
    const sideways = height * ACROSS_WEIGHT;
    return width + sideways;
  }
  const sideways = width * ACROSS_WEIGHT;
  return height + sideways;
}

function cheaperOf(best: Choice | null, candidate: Choice) {
  if (best === null) {
    return candidate;
  }
  if (candidate.cost < best.cost) {
    return candidate;
  }
  return best;
}

function landingOf(target: ClientRect, dragged: ClientRect) {
  const spare = target.width - dragged.width;
  const offset = spare / 2;
  const x = target.left + offset;
  const y = target.top + LANDING_INSET_PX;
  return { x, y };
}

/**
 * The arrows move a picked card from place to place: a column on the board, a cell of the
 * swimlanes. Each press goes to the nearest place in that direction.
 */
export const boardKeyboardCoordinates: KeyboardCoordinateGetter = (
  event,
  { context }
) => {
  const direction = DIRECTION_OF_KEY[event.code];
  if (!direction) {
    return undefined;
  }
  event.preventDefault();
  const { collisionRect, droppableRects, droppableContainers, over } = context;
  if (!collisionRect) {
    return undefined;
  }
  const fromRect = over?.rect ?? collisionRect;
  const from = centerOf(fromRect);
  let best: Choice | null = null;
  for (const container of droppableContainers.getEnabled()) {
    const rect = droppableRects.get(container.id);
    if (!rect) {
      continue;
    }
    const to = centerOf(rect);
    if (!isAhead(direction, from, to)) {
      continue;
    }
    const cost = costOf(direction, from, to);
    best = cheaperOf(best, { rect, cost });
  }
  if (!best) {
    return undefined;
  }
  return landingOf(best.rect, collisionRect);
};

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  CARD_PREFIX,
  CARDS,
  COLUMNS,
  PEOPLE,
  type Card,
  type Column,
  type ColumnId,
  type LaneId,
  type PersonId,
} from './data';

export type View = 'board' | 'lanes';

export type BoardState = {
  /** In the order they show in their column: a card that moves goes to the end, or to the place it is given. */
  cards: Card[];
  view: View;
  composerColumn: ColumnId | null;
  composerText: string;
  /** The card just added: it fades in once, in the view it was added in. */
  freshId: string | null;
  nextNumber: number;
  spoken: string;
};

export type BoardAction =
  | {
      type: 'moved';
      id: string;
      column: ColumnId;
      /** The lane it was dropped in; left out, the card keeps its person. */
      lane?: LaneId;
      /** Its place among the cards of the column; left out, it goes last. */
      index?: number;
      isDrop: boolean;
    }
  | { type: 'viewChanged'; view: View }
  | { type: 'composerOpened'; column: ColumnId }
  | { type: 'composerClosed' }
  | { type: 'composerTyped'; value: string }
  | { type: 'cardAdded' };

type Step = SessionStep<BoardState, BoardAction>;

function highestNumberOf(cards: Card[]) {
  let highest = 0;
  for (const card of cards) {
    const digits = card.number.replace(/\D/g, '');
    const value = Number(digits);
    highest = Math.max(highest, value);
  }
  return highest;
}

export const INITIAL: BoardState = {
  cards: CARDS,
  view: 'board',
  composerColumn: null,
  composerText: '',
  freshId: null,
  nextNumber: highestNumberOf(CARDS) + 1,
  spoken: '',
};

export function columnOf(id: ColumnId) {
  const column = COLUMNS.find((candidate) => candidate.id === id);
  return column ?? COLUMNS[0];
}

export function personOf(id: PersonId | null) {
  return PEOPLE.find((person) => person.id === id);
}

export function laneNameOf(lane: LaneId) {
  if (lane === 'unassigned') {
    return 'Unassigned';
  }
  const person = personOf(lane);
  if (person) {
    return person.name;
  }
  return lane;
}

function isInLane(card: Card, lane: LaneId) {
  if (lane === 'unassigned') {
    return card.assignee === null;
  }
  return card.assignee === lane;
}

export function cardsIn(cards: Card[], column: ColumnId) {
  return cards.filter((card) => card.column === column);
}

export function cardsInCell(cards: Card[], column: ColumnId, lane: LaneId) {
  const inColumn = cardsIn(cards, column);
  return inColumn.filter((card) => isInLane(card, lane));
}

export function cardsOfLane(cards: Card[], lane: LaneId) {
  return cards.filter((card) => isInLane(card, lane));
}

/** One lane per person, and one for the cards nobody holds, only while there are some. */
export function lanesOf(cards: Card[]): LaneId[] {
  const people: LaneId[] = PEOPLE.map((person) => person.id);
  const hasUnassigned = cards.some((card) => card.assignee === null);
  if (hasUnassigned) {
    return [...people, 'unassigned'];
  }
  return people;
}

export function overByOf(column: Column, count: number) {
  if (column.limit === null) {
    return 0;
  }
  const extra = count - column.limit;
  return Math.max(extra, 0);
}

/** Where every card sits and how the board is arranged: cards measure themselves again only when it changes. */
export function placementOf(state: BoardState) {
  const places = state.cards.map(
    (card) => `${card.id}:${card.column}:${card.assignee}:${card.drops}`
  );
  places.push(state.view);
  return places.join(' ');
}

function overByIn(cards: Card[], id: ColumnId) {
  const column = columnOf(id);
  const count = cardsIn(cards, id).length;
  return overByOf(column, count);
}

/** What a move changes about the limits, said once: over a limit, or back within it. */
function limitNoteOf(
  before: Card[],
  after: Card[],
  from: ColumnId | null,
  to: ColumnId
) {
  const toBefore = overByIn(before, to);
  const toAfter = overByIn(after, to);
  if (toAfter > toBefore) {
    const toName = columnOf(to).name;
    return `${toName} is over its limit by ${toAfter}`;
  }
  if (from === null) {
    return '';
  }
  const fromBefore = overByIn(before, from);
  const fromAfter = overByIn(after, from);
  const isBackWithin = fromBefore > 0 && fromAfter === 0;
  if (isBackWithin) {
    const fromName = columnOf(from).name;
    return `${fromName} is back within its limit`;
  }
  return '';
}

function assigneeAfterOf(card: Card, lane: LaneId | undefined) {
  if (lane === undefined) {
    return card.assignee;
  }
  if (lane === 'unassigned') {
    return null;
  }
  return lane;
}

/** Puts the card before the card that holds its place in the column, or after the last one. */
function placedAmong(others: Card[], card: Card, index: number | undefined) {
  if (index === undefined) {
    return [...others, card];
  }
  const column = cardsIn(others, card.column);
  const holder = column[index];
  if (!holder) {
    return [...others, card];
  }
  const at = others.indexOf(holder);
  return [...others.slice(0, at), card, ...others.slice(at)];
}

type Move = Extract<BoardAction, { type: 'moved' }>;

function moved(state: BoardState, action: Move): BoardState {
  const card = state.cards.find((candidate) => candidate.id === action.id);
  if (!card) {
    return state;
  }
  const assignee = assigneeAfterOf(card, action.lane);
  const isSameColumn = card.column === action.column;
  const isSamePerson = card.assignee === assignee;
  if (isSameColumn && isSamePerson) {
    return state;
  }
  let drops = card.drops;
  if (action.isDrop) {
    drops += 1;
  }
  const next: Card = { ...card, column: action.column, assignee, drops };
  const others = state.cards.filter((candidate) => candidate.id !== card.id);
  const cards = placedAmong(others, next, action.index);
  const spoken = limitNoteOf(state.cards, cards, card.column, action.column);
  return { ...state, cards, freshId: null, spoken };
}

function viewLineOf(view: View) {
  if (view === 'lanes') {
    return 'Cards grouped by person';
  }
  return 'All cards on one board';
}

function withNoteOf(line: string, note: string) {
  if (note === '') {
    return line;
  }
  return `${line}. ${note}`;
}

function cardAdded(state: BoardState): BoardState {
  const column = state.composerColumn;
  const title = state.composerText.trim();
  const isEmpty = title === '';
  if (!column || isEmpty) {
    return state;
  }
  const number = state.nextNumber;
  const card: Card = {
    id: `tw-${number}`,
    number: `${CARD_PREFIX}-${number}`,
    title,
    column,
    assignee: null,
    drops: 0,
  };
  const cards = [...state.cards, card];
  const note = limitNoteOf(state.cards, cards, null, column);
  const columnName = columnOf(column).name;
  const added = `${title} added to ${columnName}`;
  const spoken = withNoteOf(added, note);
  return {
    ...state,
    cards,
    composerText: '',
    freshId: card.id,
    nextNumber: number + 1,
    spoken,
  };
}

export function reducer(state: BoardState, action: BoardAction): BoardState {
  switch (action.type) {
    case 'moved':
      return moved(state, action);
    case 'viewChanged':
      return {
        ...state,
        view: action.view,
        composerColumn: null,
        freshId: null,
        spoken: viewLineOf(action.view),
      };
    case 'composerOpened':
      return { ...state, composerColumn: action.column, composerText: '' };
    case 'composerClosed':
      return { ...state, composerColumn: null, composerText: '' };
    case 'composerTyped':
      return { ...state, composerText: action.value };
    case 'cardAdded':
      return cardAdded(state);
  }
}

